        for (int letter = 0; letter < 26; ++letter) {
          if (counts[letter] > 0) {
            --counts[letter];
            buffer[depth] = (char) ('a' + letter);
            Visit(depth + 1);
            ++counts[letter];
          }
        }
      }
    }
    new Search().Visit(0);
    return result;
  }
}

